CREATE TABLE IF NOT EXISTS establishments(id BIGSERIAL PRIMARY KEY,uai VARCHAR(8) UNIQUE NOT NULL,name TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cofi_cases(id BIGSERIAL PRIMARY KEY,establishment_id BIGINT NOT NULL REFERENCES establishments(id),fiscal_year INT NOT NULL,schema_version TEXT NOT NULL DEFAULT '0.1.0',status TEXT NOT NULL DEFAULT 'DRAFT',conditions JSONB NOT NULL DEFAULT '{}'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(establishment_id,fiscal_year));
CREATE TABLE IF NOT EXISTS documents(id BIGSERIAL PRIMARY KEY,cofi_case_id BIGINT NOT NULL REFERENCES cofi_cases(id) ON DELETE CASCADE,document_code TEXT NOT NULL,title TEXT NOT NULL,producer TEXT NOT NULL,original_filename TEXT NOT NULL,mime_type TEXT NOT NULL,page_count INT,sha256 CHAR(64) NOT NULL,storage_path TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'IMPORTED',created_at TIMESTAMPTZ NOT NULL DEFAULT now(),validated_at TIMESTAMPTZ);
CREATE UNIQUE INDEX IF NOT EXISTS documents_one_active ON documents(cofi_case_id,document_code) WHERE status <> 'SUPERSEDED';
CREATE TABLE IF NOT EXISTS source_imports(id BIGSERIAL PRIMARY KEY,cofi_case_id BIGINT NOT NULL REFERENCES cofi_cases(id) ON DELETE CASCADE,source_type TEXT NOT NULL,source_version TEXT,fiscal_year INT NOT NULL,uai VARCHAR(8),filename TEXT NOT NULL,sha256 CHAR(64) NOT NULL,row_count INT NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'UPLOADED',warnings JSONB NOT NULL DEFAULT '[]'::jsonb,errors JSONB NOT NULL DEFAULT '[]'::jsonb,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),superseded_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS account_balances(id BIGSERIAL PRIMARY KEY,source_import_id BIGINT NOT NULL REFERENCES source_imports(id) ON DELETE CASCADE,cofi_case_id BIGINT NOT NULL REFERENCES cofi_cases(id) ON DELETE CASCADE,account TEXT NOT NULL,label TEXT NOT NULL DEFAULT '',opening_debit NUMERIC(18,2) NOT NULL DEFAULT 0,opening_credit NUMERIC(18,2) NOT NULL DEFAULT 0,period_debit NUMERIC(18,2) NOT NULL DEFAULT 0,period_credit NUMERIC(18,2) NOT NULL DEFAULT 0,closing_debit NUMERIC(18,2) NOT NULL DEFAULT 0,closing_credit NUMERIC(18,2) NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS account_balances_case_account ON account_balances(cofi_case_id,account);
CREATE TABLE IF NOT EXISTS audit_events(id BIGSERIAL PRIMARY KEY,cofi_case_id BIGINT REFERENCES cofi_cases(id) ON DELETE SET NULL,user_id TEXT,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT,previous_value JSONB,new_value JSONB,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
